      ans[q[st][head[st]++]] = t;
    } else if (size(0) > 0 || size(1) > 0) {
      st = size(0) > 0 ? 0 : 1;
      ans[q[st][head[st]++]] = t;
    } else {
      st = 1;
    }
    t++;
  }
  return ans;
}
